await page.evaluate(()=>{const key='inOrdineV2State',s=JSON.parse(localStorage.getItem(key));s.preferences.moneyFilters={income:'removed-filter',expense:'removed-filter'};localStorage.setItem(key,JSON.stringify(s))});await page.reload();await page.waitForSelector('.brand-logo');await page.locator('[data-go="money"]').click();await page.locator('[data-go="income"]').click();for(const kind of ['income','expense']){await page.locator('[data-go="money"]').click();await page.locator(`[data-go="${kind}"]`).click();assert.equal(await page.locator(`[data-money-filter="${kind}:all"]`).getAttribute('class'),'active',`${kind} opens on Tutte regardless of a stale saved filter`);if(kind==='expense'){assert.equal(await page.locator('.expense-head').count(),1,'Pagamenti uses the approved green header');assert.equal(await page.locator('.money-open-section .money-section-heading>b').first().evaluate(el=>getComputedStyle(el).color),'rgb(23, 35, 61)','Da pagare heading stays black');assert.equal(await page.locator('.money-open-section .money-section-heading>strong').first().evaluate(el=>getComputedStyle(el).color),'rgb(23, 35, 61)','Da pagare total stays black');}const monthOnEntry=await page.locator('.month-nav b').innerText();await page.locator(`[data-month-next="${kind}"]`).click();assert.notEqual(await page.locator('.month-nav b').innerText(),monthOnEntry,`${kind} month arrows change the viewed month`);await page.locator('.money-flow-screen [data-go="money"]').click();await page.locator(`[data-go="${kind}"]`).click();assert.equal(await page.locator('.month-nav b').innerText(),monthOnEntry,`${kind} returns to the current month after leaving and re-entering`);const labels=await page.locator('.filter-row button[data-money-filter]').allInnerTexts();assert.deepEqual(labels.slice(0,3),['Tutte',kind==='income'?'Da ricevere':'Da pagare',kind==='income'?'Ricevute':'Pagati'],`${kind} filters follow the approved order`)}await page.goto('http://127.0.0.1:4173/');await page.waitForSelector('.brand-logo');
